from .lib import Pack
from .sources import H, Q, bg, clin, fq


def build():
    p = Pack('medical_emergency', 'support', 'medical', 'both',
             'Red flags and what to do now: overdose, withdrawal, poisoning, injury, self-harm, chest pain. Call emergency services first. Never a dose, regimen or home treatment.',
             ages=('adult', '13-17'), base_tags=['emergency'])
    A = p.add
    OP, OP26 = clin('who_opioid'), clin('who_opioid_2026')
    CUT, NICE, BZ = clin('niaaa_cut'), clin('nice_cg100'), clin('benzo')
    GHB, GHB2 = clin('ghb_austin'), clin('ghb_neu')
    MH, SU = clin('who_mhgap'), clin('who_suicide')
    FA = bg('RES_H1 2.4', 'Standard first-aid wording (recovery position, stay with the person, do not leave them alone, do not induce vomiting): no source opened; the brief says to call emergency services; clinician to confirm every line.')
    STIM = bg('RES_H1 2.4', 'Stimulant overdose red flags (chest pain, very high temperature, seizure, severe agitation): standard teaching; no source opened; clinician to confirm.')

    A('safety', "If someone can't be woken, is breathing very slowly or not at all, or has blue or grey lips, call your emergency number now. Say it may be an overdose. Stay with them.", tags=['overdose', 'opioids', 'emergency'], src=[OP], risk='high', trig=['not breathing', "won't wake up", 'blue lips', 'overdose'], code='overdose')
    A('safety', "While you wait for help: try to wake them by shouting and shaking. If they don't wake, and you know how, lay them on their side with the top knee bent so their airway stays clear. Follow what the call-taker tells you.", tags=['overdose', 'recovery-position'], src=[OP, FA], ev='C', risk='high', trig=['what do i do while waiting'], code='overdose')
    A('safety', "Naloxone is a medicine that can reverse an opioid overdose. In many places it is available without a prescription or through drug services, and the World Health Organization recommends that it be available to people likely to witness an overdose. Ask a pharmacist or drug service if you can get it where you live.", tags=['naloxone', 'opioids'], src=[OP, OP26], risk='medium', trig=['naloxone', 'narcan'], code='naloxone', dns=['Where legal only; never a dose; never say it replaces calling for help.'])
    A('safety', "If naloxone is available and you have been trained to use it, use it as taught and still call your emergency number. Its effect can wear off before the opioid does, so the person needs to be watched and checked by a doctor.", tags=['naloxone', 'opioids'], src=[OP], risk='high', trig=['i have narcan', 'i have naloxone'], code='naloxone')
    A('safety', "Don't leave someone alone who has taken a lot of alcohol or drugs and is very sleepy, vomiting, or confused. Stay with them, keep them on their side, and call your emergency number if they can't be woken.", tags=['alcohol-poisoning', 'drugs', 'recovery-position'], src=[FA, bg('RES_H1 2.1', 'Alcohol poisoning red flags: unresponsive, vomiting while drowsy, slow breathing; standard teaching; clinician to confirm.')], ev='C', risk='high', trig=['passed out', 'drank too much', 'vomiting and drowsy'], code='alcohol')
    A('safety', "Please don't try to make someone vomit, give them coffee, or put them in a cold shower. These do not help and can cause harm. Call your emergency number and follow their advice.", tags=['myths', 'first-aid'], src=[FA], ev='C', risk='high', trig=['should i make him sick', 'give coffee'], code='myths')
    A('safety', "Alcohol withdrawal can be dangerous. A seizure, shaking you can't control, confusion, or seeing or hearing things that aren't there are emergencies. Call your emergency number now.", tags=['alcohol', 'withdrawal'], src=[CUT, NICE], risk='high', trig=['seizure', 'delirium', 'shaking', 'seeing things'], code='withdrawal')
    A('safety', "Stopping sleeping or anxiety tablets suddenly can cause seizures. If someone has had a fit, is very confused, or is seeing things after stopping them, call your emergency number now.", tags=['benzodiazepines', 'withdrawal'], src=[BZ], risk='high', trig=['stopped my tablets', 'stopped xanax', 'fit', 'convulsion'], code='withdrawal')
    A('safety', "GHB, GBL and 1,4-BD withdrawal can start within hours and become life-threatening, with confusion, agitation, seeing things and seizures. If someone using these regularly has any of those signs, call your emergency number now.", tags=['ghb', 'withdrawal'], src=[GHB, GHB2], risk='high', trig=['ghb', 'gbl', 'tremor', 'agitated'], code='withdrawal')
    A('safety', "Opioid withdrawal is miserable but is rarely life-threatening on its own. If someone has severe vomiting and cannot keep fluids down, or is very faint or confused, get medical help today.", tags=['opioids', 'withdrawal'], src=[bg('RES_H1 2.4', 'Opioid withdrawal severity: standard teaching; clinician to confirm.'), OP26], ev='C', risk='high', trig=['dope sick', 'opioid withdrawal'], code='withdrawal')
    A('safety', "Stimulants such as cocaine, amphetamine and captagon can cause chest pain, a very fast heartbeat, a very high temperature, seizures, or severe confusion. If any of these happen, call your emergency number now and cool the person down while you wait.", tags=['stimulants', 'overdose'], src=[STIM], ev='C', risk='high', trig=['chest pain', 'overheating', 'fit', 'racing heart', 'cocaine', 'meth'], code='stimulants')
    A('safety', "Chest pain, trouble breathing, a fit, fainting, sudden weakness on one side, or heavy bleeding are emergencies. Call your emergency number now. Don't drive yourself.", tags=['red-flags', 'general'], src=[FA], ev='C', risk='high', trig=['chest pain', "can't breathe", 'fainting', 'bleeding'], code='general')
    A('safety', "If you or someone has taken pills, drunk something harmful, or swallowed a chemical, call your emergency number or the poison centre now. Say what and roughly when. Don't wait for symptoms.", tags=['poison', 'ingestion'], src=[MH, FA], ev='C', risk='high', trig=['swallowed', 'took pills', 'drank bleach'], code='poison')
    A('safety', "If you have hurt yourself and are bleeding, press firmly on the wound with a clean cloth and call your emergency number. You deserve care, not judgement.", tags=['self-harm', 'injury'], src=[MH, FA], ev='C', risk='high', trig=['i cut myself', 'bleeding', 'cut too deep'], code='selfharm')
    A('safety', "If you are thinking about ending your life, call your emergency number or a crisis line now. If you can, don't be alone, and keep away from anything you could use to hurt yourself.", tags=['suicide', 'crisis'], src=[SU, MH], risk='high', trig=['kill myself', 'end my life', 'suicide'], code='suicide', dns=['Join with helplines.json scope suicide.'], stage=['crisis'])
    A('safety', "If someone has been seriously hurt by another person, or is in immediate danger, call your emergency number. Get yourself somewhere safe first, if you can.", tags=['violence', 'abuse'], src=[clin('who_vaw')], risk='high', trig=['he is beating', 'attacked', 'stabbed'], code='violence')
    A('safety', "If someone has choked or strangled you, even if you feel fine afterwards, get medical care today. Hidden injuries can be serious.", tags=['strangulation', 'abuse'], src=[bg('RES_H1 6', 'Strangulation can cause delayed internal injury; standard domestic-abuse and emergency-medicine teaching; clinician to confirm.')], ev='C', risk='high', trig=['choked me', 'strangled'], code='violence')
    A('safety', "If a child has swallowed something, taken someone's medicine, or is hard to wake, call your emergency number now.", tags=['child', 'poison'], src=[FA], ev='C', risk='high', trig=['my child took', 'the baby swallowed'], code='child')

    A('ask', "Is the person breathing normally and can you wake them?", tags=['triage'], src=[OP, FA], ev='C', risk='high', ask=True, code='triage', dns=['One question only. If no, show the first overdose card immediately.'])
    A('ask', "Have you called your emergency number yet?", tags=['triage'], src=[FA], ev='C', risk='high', ask=True, code='triage')
    A('ask', "Are you safe where you are right now?", tags=['triage', 'safety'], src=[FA], ev='C', risk='high', ask=True, code='triage')

    A('orient', "I'm an app, not an emergency service, and I can't see what's happening. If this is an emergency, call your emergency number first. I'll stay with you.", tags=['honesty', 'opening'], src=[FA], ev='C', risk='high', code='orient', fixed=True)
    A('orient', "Tell me what's happening in a few words. If someone isn't breathing or can't be woken, call now.", tags=['opening'], src=[FA], ev='C', risk='high', code='orient', fixed=True)

    A('explain', "Calling for help for an overdose is the right thing to do. In many places there are protections for people who call, and you can ask the call-taker about it. Saving a life matters more than any worry about getting in trouble.", tags=['fear-of-calling', 'legal'], src=[bg('RES_H1 7.7', 'Good Samaritan protections vary by country; local legal review needed before stating any protection.')], ev='C', risk='high', trig=['will i get in trouble', 'afraid to call', 'police'], code='fear', dns=['Needs local legal review; do not promise a protection.'])
    A('explain', "You can call without giving a name. Say where you are, what happened and what you can see. Stay on the line until they tell you to hang up.", tags=['calling', 'script'], src=[FA], ev='C', risk='high', trig=['what do i say', 'how do i call'], code='calling')
    A('explain', "If you are worried a drink or medicine may have been given to you without your knowledge, get to a safe place and ask for medical help. Tell the staff you are worried.", tags=['spiking'], src=[bg('RES_H1 6', 'Drink spiking: seek medical help; standard teaching; clinician to confirm.')], ev='C', risk='high', trig=['spiked', 'drugged my drink'], code='spiking')

    A('plan-step', "Right now: call your emergency number, then come back and tell me what they said. I'm here.", tags=['next-step'], src=[FA], ev='C', risk='high', ask=True, code='next')
    A('plan-step', "Right now: stay with the person, keep checking their breathing, and don't give them anything to eat or drink.", tags=['next-step', 'stay'], src=[FA], ev='C', risk='high', ask=True, code='next')

    A('referral', "The numbers for emergency services and poison centres in your country are listed below. If yours isn't there, use the local emergency number you know.", tags=['emergency-numbers'], dns=['Join with helplines.json scope emergency; never type a number; honest if unlisted.'], fixed=True, code='numbers', trig=['emergency number', 'what number'])
    A('referral', "After an emergency, see a doctor, even if you feel better. Many problems show up later.", tags=['follow-up', 'doctor'], src=[FA], ev='C', fixed=True, code='followup')

    A('islamic', "The Qur'an says that whoever saves a life, it is as if they saved all of humanity. Calling for help now is the right thing to do before anything else, including prayer.", src=[Q('5:32', 'RES_H2 6.1')], tags=['saving-life'], trig=['i should pray first', 'it is not allowed to call'], code='priority', dns=['No ruling about prayer timing is given; scholar to confirm framing.'])
    A('islamic', "The Prophet encouraged seeking treatment, saying Allah has not made an illness without a cure. Getting urgent medical help is in keeping with that.", src=[H('ibnmajah:3438', 'RES_H2 2.5'), H('ibnmajah:3436', 'RES_H2 2.5')], tags=['treatment'], trig=['is it tawakkul', 'should i leave it to allah'], code='treatment')
    A('islamic', "Scholars differ on some questions about medicines and treatment in an emergency, and I can't give a ruling. In an emergency, get help first. A scholar can answer the question afterwards.", src=[fq('Scholars differ on necessity (darura) and medicines; Dar al-Ifta al-Misriyyah fatwa 5983 (1979) and the darura conditions in Azahar et al., KATHA 2024', 'RES_H2 3.5', 'institution')], tags=['darura', 'fiqh', 'scholar-handoff'], disputed=True, schools=['hanafi', 'maliki', 'shafii', 'hanbali'], ev='D', trig=['is naloxone halal', 'is the medicine haram'], code='fiqh')

    A('family', "If you are with someone who may be in danger, stay calm, speak to them, and call your emergency number. You do not need to be sure it is an emergency.", tags=['bystander'], src=[FA], ev='C', risk='high', fixed=True, code='bystander')
    A('summary', "Right now the most important thing is your emergency number. When it's over, I'm here to talk through what happened.", tags=['summary'], src=[FA], ev='C', code='summary')
    return [p]
